def v2(n):
    if n == 0: return 999
    c = 0
    while n % 2 == 0:
        c += 1
        n //= 2
    return c

# Faster: only check small c values and specific alpha
candidates = []
for c in range(2, 30):
    K_odd = (1 << (2*c-2)) - 1  # 2^(2c-2) - 1
    # Get odd divisors
    divs = []
    d = 1
    while d * d <= K_odd:
        if K_odd % d == 0:
            e = K_odd // d
            divs.append((d, e))
            if d != e:
                divs.append((e, d))
        d += 2
    for alpha in [3, 4, 5, 6]:
        for d, e in divs:
            for j in range(0, 2*alpha-1):
                val = (1 << j) * d + (1 << (2*alpha-2-j)) * e - (1 << (alpha+c-1))
                if val > 0 and val % 2 == 0:
                    a = val // 2
                    if a >= 5 and a % 2 == 1:
                        a2m1 = a*a - 1
                        actual_alpha = v2(a2m1)
                        if actual_alpha == alpha:
                            A = a2m1 >> alpha
                            v1A2 = v2(abs(1 - A*A)) if A*A != 1 else 999
                            if v1A2 > alpha:
                                candidates.append((a, alpha, c))
                                if len(candidates) <= 50:
                                    print(f"  a={a}, alpha={alpha}, c={c}")

print(f"\nTotal Case 2 candidates: {len(candidates)}")
